/**
 * Universal translation resolver
 * @param {string} key - Dot-delimited translation key (e.g. 'dashboard.greeting')
 * @param {string} lang - Language code (e.g. 'en', 'kn', 'hi', 'te')
 * @param {object} params - Dynamic interpolation variables (e.g. { name: 'Sharada' })
 * @returns {string} Localized string
 */
export function t(key, lang = 'en', params = {}) {
  if (!key) return '';
  const cleanLang = (lang || 'en').toLowerCase().split('-')[0].trim();
  const parts = key.split('.');

  // 1. Try target language dictionary
  let val = TRANSLATIONS[cleanLang];
  for (const part of parts) {
    if (val && typeof val === 'object' && part in val) {
      val = val[part];
    } else {
      val = null;
      break;
    }
  }

  // 2. If missing in target language, fall back STRICTLY to English (never to Kannada or random language)
  if (val === null || val === undefined) {
    let fallbackVal = TRANSLATIONS['en'];
    for (const part of parts) {
      if (fallbackVal && typeof fallbackVal === 'object' && part in fallbackVal) {
        fallbackVal = fallbackVal[part];
      } else {
        fallbackVal = null;
        break;
      }
    }
    val = (fallbackVal !== null && fallbackVal !== undefined) ? fallbackVal : parts[parts.length - 1];
  }

  // 3. Perform parameter interpolation
  if (typeof val === 'string' && params && Object.keys(params).length > 0) {
    let interpolated = val;
    for (const [k, v] of Object.entries(params)) {
      interpolated = interpolated.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return interpolated;
  }

  return val;
}

/**
 * Format localized date based on language locale
 */
export function formatLocalizedDate(dateObj, lang = 'en', options = {}) {
  const d = (dateObj instanceof Date) ? dateObj : new Date(dateObj || Date.now());
  const bcpMap = {
    en: 'en-IN', kn: 'kn-IN', hi: 'hi-IN', te: 'te-IN', ta: 'ta-IN',
    mr: 'mr-IN', bn: 'bn-IN', gu: 'gu-IN', ml: 'ml-IN', pa: 'pa-IN',
    or: 'or-IN', as: 'as-IN', ur: 'ur-IN', sa: 'sa-IN', ks: 'ks-IN',
    kok: 'kok-IN', mai: 'mai-IN', mni: 'mni-IN', ne: 'ne-NP',
    sat: 'sat-IN', sd: 'sd-IN', doi: 'doi-IN', brx: 'brx-IN'
  };
  const locale = bcpMap[(lang || 'en').toLowerCase().split('-')[0]] || 'en-IN';
  const defaultOpts = {
    weekday: 'short',
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  };
  try {
    return new Intl.DateTimeFormat(locale, { ...defaultOpts, ...options }).format(d);
  } catch {
    return d.toDateString();
  }
}
